create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade,nama text not null default '',role text not null default 'viewer' check(role in ('hr_admin','viewer')));
create function public.is_hr_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='hr_admin')$$;
create function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,nama) values(new.id,coalesce(new.raw_user_meta_data->>'nama','Pengguna')); return new; end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_profile();
create table public.employees(id uuid primary key default gen_random_uuid(),nama text not null check(length(nama) between 1 and 120),gender text not null check(gender in ('Perempuan','Laki-laki')),tgl_lahir date not null,departemen text not null,jabatan text not null,tgl_masuk date not null,tgl_keluar date,alasan_keluar text,gaji_pokok numeric not null check(gaji_pokok>=0),status text not null check(status in ('aktif','keluar')),check(tgl_keluar is null or tgl_keluar>=tgl_masuk));
create table public.attendance(id uuid primary key default gen_random_uuid(),employee_id uuid not null references employees on delete cascade,tanggal date not null,status text not null check(status in ('hadir','telat','izin','cuti','alpa')),jam_lembur numeric not null default 0 check(jam_lembur>=0),unique(employee_id,tanggal));
create table public.recruitment(id uuid primary key default gen_random_uuid(),posisi text not null,departemen text not null,sumber text not null,tgl_buka date not null,tgl_terisi date,jumlah_pelamar int not null check(jumlah_pelamar>=0),check(tgl_terisi is null or tgl_terisi>=tgl_buka));
create table public.performance(id uuid primary key default gen_random_uuid(),employee_id uuid not null references employees on delete cascade,periode date not null,skor numeric not null check(skor between 1 and 5));
create table public.training(id uuid primary key default gen_random_uuid(),employee_id uuid not null references employees on delete cascade,nama_pelatihan text not null,jam numeric not null check(jam>=0),tanggal date not null);
create table public.ai_cache(kunci text primary key,isi text not null,dibuat_pada timestamptz not null default now());
create table public.audit_log(id bigint generated always as identity primary key,user_id uuid references auth.users on delete set null,aksi text not null,detail jsonb,waktu timestamptz not null default now());
create index on audit_log(user_id,waktu);
create index on attendance(tanggal,employee_id);
create index on employees(departemen,tgl_masuk,tgl_keluar);
do $$declare t text; begin foreach t in array array['profiles','employees','attendance','recruitment','performance','training','audit_log','ai_cache'] loop execute format('alter table public.%I enable row level security',t); end loop;
foreach t in array array['employees','attendance','recruitment','performance','training'] loop
execute format('create policy read_authenticated on public.%I for select to authenticated using(true)',t);
execute format('create policy write_admin on public.%I for all to authenticated using(public.is_hr_admin()) with check(public.is_hr_admin())',t);
end loop; end$$;
create policy profiles_read on profiles for select to authenticated using(true);
create policy profiles_admin on profiles for all to authenticated using(is_hr_admin()) with check(is_hr_admin());
create policy audit_read on audit_log for select to authenticated using(is_hr_admin());
-- Audit and cache writes are service-only; no authenticated write policies.
create function public.audit_changes() returns trigger language plpgsql security definer set search_path=public as $$begin insert into audit_log(user_id,aksi,detail) values(auth.uid(),tg_table_name||':'||tg_op,jsonb_build_object('id',coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id'))); return coalesce(new,old); end$$;
do $$declare t text; begin foreach t in array array['employees','attendance','recruitment','performance','training','profiles'] loop execute format('create trigger audit_change after insert or update or delete on public.%I for each row execute function public.audit_changes()',t); end loop; end$$;
-- RPCs are invoker functions: RLS applies to every source table.
create function public.rpc_ringkasan(p_dari date,p_sampai date,p_departemen text default null) returns jsonb language plpgsql stable security invoker set search_path=public as $$declare result jsonb; begin if p_dari is null or p_sampai is null or p_sampai<p_dari or p_sampai-p_dari>1096 then raise exception 'Periode tidak valid (maksimal 3 tahun)'; end if; with e as(select *,extract(year from age(p_sampai,tgl_lahir)) usia from employees where tgl_masuk<=p_sampai and (tgl_keluar is null or tgl_keluar>p_sampai) and (p_departemen is null or departemen=p_departemen)) select jsonb_build_object('total_aktif',(select count(*) from e),'rata_masa_kerja_tahun',(select coalesce(round(avg((p_sampai-tgl_masuk)/365.25),2),0) from e),'gender',(select coalesce(jsonb_agg(x),'[]') from(select gender label,count(*) nilai from e group by gender)x),'usia',(select coalesce(jsonb_agg(x),'[]') from(select case when usia<30 then '<30' when usia<40 then '30–39' when usia<50 then '40–49' else '50+' end label,count(*) nilai from e group by 1)x),'departemen',(select coalesce(jsonb_agg(x),'[]') from(select departemen label,count(*) nilai from e group by departemen order by departemen)x)) into result; return result; end$$;
revoke all on function public.rpc_ringkasan(date,date,text) from public,anon; grant execute on function public.rpc_ringkasan(date,date,text) to authenticated;
create function public.rpc_turnover(p_dari date,p_sampai date,p_departemen text default null) returns jsonb language plpgsql stable security invoker set search_path=public as $$declare result jsonb; begin if p_dari is null or p_sampai is null or p_sampai<p_dari or p_sampai-p_dari>1096 then raise exception 'Periode tidak valid (maksimal 3 tahun)'; end if; with e as(select * from employees where p_departemen is null or departemen=p_departemen),m as(select d::date awal,(d+interval '1 month'-interval '1 day')::date akhir from generate_series(date_trunc('month',p_dari),date_trunc('month',p_sampai),interval '1 month')d),r as(select to_char(awal,'YYYY-MM') label,(select count(*) from e where tgl_keluar between greatest(awal,p_dari) and least(akhir,p_sampai)) keluar,((select count(*) from e where tgl_masuk<=greatest(awal,p_dari) and (tgl_keluar is null or tgl_keluar>=greatest(awal,p_dari)))+(select count(*) from e where tgl_masuk<=least(akhir,p_sampai) and (tgl_keluar is null or tgl_keluar>least(akhir,p_sampai))))/2.0 basis from m) select jsonb_build_object('jumlah_keluar',(select count(*) from e where tgl_keluar between p_dari and p_sampai),'bulanan',(select coalesce(jsonb_agg(x),'[]') from(select label,coalesce(round(100*keluar/nullif(basis,0),2),0) nilai from r)x),'departemen',(select coalesce(jsonb_agg(x),'[]') from(select departemen label,coalesce(round(100.0*count(*) filter(where tgl_keluar between p_dari and p_sampai)/nullif((count(*) filter(where tgl_masuk<=p_dari and(tgl_keluar is null or tgl_keluar>=p_dari))+count(*) filter(where tgl_masuk<=p_sampai and(tgl_keluar is null or tgl_keluar>p_sampai)))/2.0,0),2),0) nilai,count(*) filter(where tgl_keluar between p_dari and p_sampai) jumlah_keluar from e group by 1)x),'alasan',(select coalesce(jsonb_agg(x),'[]') from(select coalesce(alasan_keluar,'Tidak dicatat') label,count(*) nilai from e where tgl_keluar between p_dari and p_sampai group by 1)x)) into result; return result; end$$;
revoke all on function public.rpc_turnover(date,date,text) from public,anon; grant execute on function public.rpc_turnover(date,date,text) to authenticated;
create function public.rpc_absensi(p_dari date,p_sampai date,p_departemen text default null) returns jsonb language plpgsql stable security invoker set search_path=public as $$declare result jsonb; begin if p_dari is null or p_sampai is null or p_sampai<p_dari or p_sampai-p_dari>1096 then raise exception 'Periode tidak valid (maksimal 3 tahun)'; end if; with a as(select a.* from attendance a join employees e on e.id=a.employee_id where tanggal between p_dari and p_sampai and(p_departemen is null or e.departemen=p_departemen)) select jsonb_build_object('tingkat_kehadiran',coalesce(round(100.0*count(*) filter(where status in ('hadir','telat'))/nullif(count(*),0),2),0),'tingkat_keterlambatan',coalesce(round(100.0*count(*) filter(where status='telat')/nullif(count(*),0),2),0),'jumlah_catatan',count(*),'bulanan',(select coalesce(jsonb_agg(x),'[]') from(select to_char(tanggal,'YYYY-MM') label,count(*) filter(where status='cuti') nilai from a group by 1 order by 1)x),'status',(select coalesce(jsonb_agg(x),'[]') from(select status label,count(*) nilai from a group by 1)x)) from a into result; return result; end$$;
revoke all on function public.rpc_absensi(date,date,text) from public,anon; grant execute on function public.rpc_absensi(date,date,text) to authenticated;
create function public.rpc_biaya(p_dari date,p_sampai date,p_departemen text default null) returns jsonb language plpgsql stable security invoker set search_path=public as $$declare result jsonb; begin if p_dari is null or p_sampai is null or p_sampai<p_dari or p_sampai-p_dari>1096 then raise exception 'Periode tidak valid (maksimal 3 tahun)'; end if; with e as(select * from employees where p_departemen is null or departemen=p_departemen),pay as(select e.id,e.departemen,sum(e.gaji_pokok*greatest(0,least(coalesce(e.tgl_keluar-1,p_sampai),p_sampai,(m+interval '1 month'-interval '1 day')::date)-greatest(e.tgl_masuk,p_dari,m::date)+1)/extract(day from m+interval '1 month'-interval '1 day')) total from e cross join generate_series(date_trunc('month',p_dari),date_trunc('month',p_sampai),interval '1 month')m group by e.id,e.departemen),o as(select coalesce(sum(a.jam_lembur*e.gaji_pokok/173*1.5),0) total from attendance a join e on e.id=a.employee_id where a.tanggal between p_dari and p_sampai) select jsonb_build_object('total_payroll',coalesce((select round(sum(total),0) from pay),0),'biaya_lembur',(select round(total,0) from o),'departemen',(select coalesce(jsonb_agg(x),'[]') from(select departemen label,round(sum(total),0) nilai,round(avg(nullif(total,0)),0) rata_rata from pay group by 1)x)) into result; return result; end$$;
revoke all on function public.rpc_biaya(date,date,text) from public,anon; grant execute on function public.rpc_biaya(date,date,text) to authenticated;
create function public.rpc_rekrutmen(p_dari date,p_sampai date,p_departemen text default null) returns jsonb language plpgsql stable security invoker set search_path=public as $$declare result jsonb; begin if p_dari is null or p_sampai is null or p_sampai<p_dari or p_sampai-p_dari>1096 then raise exception 'Periode tidak valid (maksimal 3 tahun)'; end if; with r as(select * from recruitment where tgl_buka between p_dari and p_sampai and(p_departemen is null or departemen=p_departemen)) select jsonb_build_object('jumlah_pelamar',coalesce(sum(jumlah_pelamar),0),'time_to_hire_hari',coalesce(round(avg(tgl_terisi-tgl_buka) filter(where tgl_terisi<=p_sampai),2),0),'lowongan',count(*),'sumber',(select coalesce(jsonb_agg(x),'[]') from(select sumber label,sum(jumlah_pelamar) nilai from r group by 1 order by 2 desc)x),'departemen',(select coalesce(jsonb_agg(x),'[]') from(select departemen label,count(*) nilai from r group by 1)x)) from r into result; return result; end$$;
revoke all on function public.rpc_rekrutmen(date,date,text) from public,anon; grant execute on function public.rpc_rekrutmen(date,date,text) to authenticated;
create function public.rpc_kinerja_pelatihan(p_dari date,p_sampai date,p_departemen text default null) returns jsonb language plpgsql stable security invoker set search_path=public as $$declare result jsonb; begin if p_dari is null or p_sampai is null or p_sampai<p_dari or p_sampai-p_dari>1096 then raise exception 'Periode tidak valid (maksimal 3 tahun)'; end if; with e as(select * from employees where p_departemen is null or departemen=p_departemen),p as(select p.* from performance p join e on e.id=p.employee_id where periode between p_dari and p_sampai),t as(select t.* from training t join e on e.id=t.employee_id where tanggal between p_dari and p_sampai) select jsonb_build_object('rata_skor',coalesce((select round(avg(skor),2) from p),0),'total_jam_pelatihan',coalesce((select sum(jam) from t),0),'skor',(select coalesce(jsonb_agg(x),'[]') from(select skor::text label,count(*) nilai from p group by skor order by skor)x),'departemen',(select coalesce(jsonb_agg(x),'[]') from(select e.departemen label,round(coalesce(sum(t.jam),0)/count(distinct e.id),2) nilai from e left join t on t.employee_id=e.id where e.tgl_masuk<=p_sampai and(e.tgl_keluar is null or e.tgl_keluar>=p_dari) group by 1)x)) into result; return result; end$$;
revoke all on function public.rpc_kinerja_pelatihan(date,date,text) from public,anon; grant execute on function public.rpc_kinerja_pelatihan(date,date,text) to authenticated;
-- Serialize admission per user so simultaneous requests cannot bypass the limit.
create function public.admit_ai(p_user uuid) returns boolean language plpgsql security definer set search_path=public as $$begin
perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
if (select count(*) from audit_log where user_id=p_user and aksi='ai_request' and waktu>now()-interval '1 hour')>=20 then return false; end if;
insert into audit_log(user_id,aksi,detail) values(p_user,'ai_request','{}'); return true; end$$;
revoke all on function public.admit_ai(uuid) from public,anon,authenticated;
grant execute on function public.admit_ai(uuid) to service_role;
-- Explicit grants; RLS remains the authorization boundary.
grant usage on schema public to authenticated,service_role;
grant select,insert,update,delete on profiles,employees,attendance,recruitment,performance,training to authenticated;
grant select on audit_log to authenticated;
revoke all on ai_cache from anon,authenticated;
grant all on all tables in schema public to service_role;
grant usage,select on all sequences in schema public to service_role;
